import React, { useState } from "react";
import Layout from "../components/layout";
import { graphql, PageProps } from "gatsby";
import { useTranslation } from "gatsby-plugin-react-i18next";
import Palette from "../components/palette";
import images from "../images";
import Carousel from "../components/carousel";
import { Helmet } from "react-helmet";
import { UserProfile } from "../interfaces";
import data from "../data/data.json";
import Gallery from "../components/gallery";
import Modal from "../components/modal";
import ContactForm from "../components/contactForm";

const userData: UserProfile = data;

const IndexPage: React.FC<PageProps> = () => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const { t } = useTranslation();

  const carouselImages = [
    { src: images.gallery_1.src, alt: images.gallery_1.alt },
    { src: images.gallery_2.src, alt: images.gallery_2.alt },
    { src: images.gallery_3.src, alt: images.gallery_3.alt },
    { src: images.gallery_4.src, alt: images.gallery_4.alt },
    { src: images.gallery_5.src, alt: images.gallery_5.alt },
  ];

  const carouselTextContent = Array.from({ length: 5 }, (_, index) => {
    const slideNum = index + 1;
    return {
      content: (
        <div className="m-2 sm:m-16 w-full sm:w-2/3">
          <h2 className="text-lg sm:text-7xl uppercase mb-1">
            {t(`home.carousel.slide${slideNum}.title`)}
          </h2>
          <p className="text-xs sm:text-base">
            {t(`home.carousel.slide${slideNum}.subtitle`)}
          </p>
        </div>
      ),
      positionClass: "",
    };
  });

  return (
    <>
      <Helmet>
        <title>{userData.keywords.titleLanding}</title>
        <meta name="description" content={userData.keywords.metaLanding} />
      </Helmet>

      <Layout>
        {/* <Palette /> */}
        <section className={styles.container}>
          <article className={`${styles.section} w-full flex items-end mt-0`}>
            <Carousel
              images={carouselImages}
              textOverlay={carouselTextContent}
              speed={6000}
            />
          </article>
          {/* Sección de Galería */}
          <article className={styles.section}>
            <Gallery />
          </article>
          <article className={`flex-col max-w-full sm:max-w-[1488px] ${styles.section}`}>
            <div className="j">
              <h2 className="text-3xl text-accent mb-6">{t("home.ourClients") || ""}</h2>
              
            </div>
            <div className={styles.clientsWrapper}>
              <img
                src={images.client1.src}
                alt={images.client1.alt}
                className={styles.clientItem}
              />
              <img
                src={images.client2.src}
                alt={images.client2.alt}
                className={styles.clientItem}
              />
              <img
                src={images.client3.src}
                alt={images.client3.alt}
                className={styles.clientItem}
              />
              <img
                src={images.client4.src}
                alt={images.client4.alt}
                className={styles.clientItem}
              />
              <img
                src={images.client5.src}
                alt={images.client5.alt}
                className={styles.clientItem}
              />

            </div>
          </article>

          <article className="my-6">
            <Modal
              isOpen={isModalOpen}
              setIsOpen={setIsModalOpen}
              buttonLabel={t("form.contactUsButton") || ""}
              title="Contáctanos"
            >
              <ContactForm />
            </Modal>
          </article>
        </section>
      </Layout>
    </>
  );
};

export default IndexPage;

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  container: "flex flex-col justify-center items-center w-full ",
  // section: "bg-secondary-50 border-secondary flex mb-8 w-full border shadow-md",
  section: "flex mb-8 w-full",
  title: "text-4xl text-accent",
  galleryWrapper: "flex flex-col justify-center items-center w-full",
  clientsWrapper:
    "flex flex-col md:flex-row items-center justify-center gap-4 w-full",
  clientItem: "h-16 sm:h-24 object-contain mx-4 shadow-2xl",
};
